    52→// ============================================================
    53→
    54→/**
    55→ * Index for tracking spec-task alignment.
    56→ * Build once when loading, then query for alignment issues.
    57→ */
    58→export class AlignmentIndex {
    59→  /** spec ULID → task ULIDs that reference it */
    60→  private specToTasks = new Map<string, string[]>();
    61→
    62→  /** task ULID → spec ULID it references */
    63→  private taskToSpec = new Map<string, string>();
    64→
    65→  /** All spec items by ULID */
    66→  private specItems = new Map<string, LoadedSpecItem>();
    67→
    68→  /** All tasks by ULID */
    69→  private tasks = new Map<string, LoadedTask>();
    70→
    71→  /**
    72→   * Build index from loaded items
    73→   */
    74→  constructor(tasks: LoadedTask[], items: LoadedSpecItem[]) {
    75→    // Index spec items
    76→    for (const item of items) {
    77→      this.specItems.set(item._ulid, item);
    78→      this.specToTasks.set(item._ulid, []);
    79→    }
    80→
    81→    // Index tasks and build reverse mapping
    82→    for (const task of tasks) {
    83→      this.tasks.set(task._ulid, task);
    84→
    85→      if (task.spec_ref) {
    86→        // Store the raw ref - we'll resolve it when needed
    87→        this.taskToSpec.set(task._ulid, task.spec_ref);
    88→      }
    89→    }
    90→  }
    91→
    92→  /**
    93→   * Resolve task spec_refs and build the bidirectional index.
    94→   * Must be called with a ReferenceIndex to resolve @refs.
    95→   */
    96→  buildLinks(refIndex: ReferenceIndex): void {
    97→    for (const [taskUlid, specRef] of this.taskToSpec) {
    98→      const result = refIndex.resolve(specRef);
    99→      if (result.ok) {
   100→        const specUlid = result.ulid;
   101→        const existing = this.specToTasks.get(specUlid);
   102→        if (existing) {
   103→          existing.push(taskUlid);
   104→        }
   105→      }
   106→    }
   107→  }
   108→
   109→  /**
   110→   * Get tasks that implement a spec item
   111→   */
   112→  getTasksForSpec(specUlid: string): LoadedTask[] {
   113→    const taskUlids = this.specToTasks.get(specUlid) || [];
   114→    return taskUlids
   115→      .map((ulid) => this.tasks.get(ulid))
   116→      .filter((t): t is LoadedTask => t !== undefined);
   117→  }
   118→
   119→  /**
   120→   * Get the spec item a task implements
   121→   */
   122→  getSpecForTask(
   123→    taskUlid: string,
   124→    refIndex: ReferenceIndex,
   125→  ): LoadedSpecItem | undefined {
   126→    const specRef = this.taskToSpec.get(taskUlid);
   127→    if (!specRef) return undefined;
   128→
   129→    const result = refIndex.resolve(specRef);
   130→    if (result.ok) {
   131→      return this.specItems.get(result.ulid);
   132→    }
   133→    return undefined;
   134→  }
   135→
   136→  /**
   137→   * Calculate expected implementation status based on linked task statuses
   138→   */
   139→  calculateExpectedStatus(specUlid: string): ImplementationStatus {
   140→    const taskUlids = this.specToTasks.get(specUlid) || [];
   141→    if (taskUlids.length === 0) {
   142→      return "not_started";
   143→    }
   144→
   145→    const tasks = taskUlids
   146→      .map((ulid) => this.tasks.get(ulid))
   147→      .filter((t): t is LoadedTask => t !== undefined);
   148→
   149→    if (tasks.length === 0) {
   150→      return "not_started";
   151→    }
   152→
   153→    // Check task statuses
   154→    const hasActiveWork = tasks.some(
   155→      (t) =>
   156→        t.status === "in_progress" ||
   157→        t.status === "pending_review" ||
   158→        t.status === "needs_work",
   159→    );
   160→    const allCompleted = tasks.every((t) => t.status === "completed");
   161→    const someCompleted = tasks.some((t) => t.status === "completed");
   162→
   163→    if (allCompleted) {
   164→      return "implemented";
   165→    }
   166→    if (hasActiveWork || someCompleted) {
   167→      return "in_progress";
   168→    }
   169→    return "not_started";
   170→  }
   171→
   172→  /**
   173→   * Get implementation summary for a spec item
   174→   */
   175→  getImplementationSummary(
   176→    specUlid: string,
   177→  ): SpecImplementationSummary | undefined {
   178→    const spec = this.specItems.get(specUlid);
   179→    if (!spec) return undefined;
   180→
   181→    const taskUlids = this.specToTasks.get(specUlid) || [];
   182→    const linkedTasks: LinkedTaskSummary[] = taskUlids
   183→      .map((ulid) => this.tasks.get(ulid))
   184→      .filter((t): t is LoadedTask => t !== undefined)
   185→      .map((t) => ({
   186→        taskUlid: t._ulid,
   187→        taskTitle: t.title,
   188→        taskStatus: t.status,
   189→        hasNotes: t.notes.length > 0,
   190→      }));
   191→
   192→    const currentStatus = spec.status?.implementation || "not_started";
   193→    const expectedStatus = this.calculateExpectedStatus(specUlid);
   194→
   195→    return {
   196→      specUlid,
   197→      specTitle: spec.title,
   198→      currentStatus,
   199→      expectedStatus,
   200→      linkedTasks,
   201→      isAligned: currentStatus === expectedStatus,
   202→    };
   203→  }
   204→
   205→  /**
   206→   * Find all alignment issues
   207→   */
   208→  findAlignmentWarnings(): AlignmentWarning[] {
   209→    const warnings: AlignmentWarning[] = [];
   210→
   211→    // Check each spec item
   212→    for (const [specUlid, spec] of this.specItems) {
   213→      const taskUlids = this.specToTasks.get(specUlid) || [];
   214→      const currentStatus = spec.status?.implementation || "not_started";
   215→      const expectedStatus = this.calculateExpectedStatus(specUlid);
   216→
   217→      // Orphaned spec (no tasks)
   218→      // AC: @trait-retrospective ac-1
   219→      // Skip retrospective specs from orphaned warnings
   220→      // Policy: warn for not_started and in_progress (suspicious), but trust
   221→      // implemented/verified as baseline history predating the task system.
   222→      const isRetrospective = spec.traits?.includes("@trait-retrospective");
   223→      if (
   224→        taskUlids.length === 0 &&
   225→        (currentStatus === "not_started" || currentStatus === "in_progress") &&
   226→        !isRetrospective
   227→      ) {
   228→        warnings.push({
   229→          type: "orphaned_spec",
   230→          specUlid,
   231→          specTitle: spec.title,
   232→          message: `Spec item "${spec.title}" has no implementing tasks`,
   233→        });
   234→      }
   235→
   236→      // Status mismatch (only when tasks exist — no-task specs are handled above
   237→      // for not_started/in_progress; implemented/verified are trusted as baseline)
   238→      if (taskUlids.length > 0 && currentStatus !== expectedStatus) {
   239→        warnings.push({
   240→          type: "status_mismatch",
   241→          specUlid,
   242→          specTitle: spec.title,
   243→          message: `Spec "${spec.title}" status is "${currentStatus}" but should be "${expectedStatus}" based on task progress`,
   244→        });
   245→      }
   246→    }
   247→
   248→    // Check completed tasks with stale spec status
   249→    for (const [taskUlid, task] of this.tasks) {
   250→      if (task.status === "completed" && task.spec_ref) {
   251→        const specRef = this.taskToSpec.get(taskUlid);
   252→        if (specRef) {
   253→          // Note: We already checked this via spec iteration above
   254→          // But this provides task-centric context
   255→        }
   256→      }
   257→    }
   258→
   259→    return warnings;
   260→  }
   261→
   262→  /**
   263→   * Get all spec items with their implementation summary
   264→   */
   265→  getAllImplementationSummaries(): SpecImplementationSummary[] {
   266→    const summaries: SpecImplementationSummary[] = [];
   267→    for (const specUlid of this.specItems.keys()) {
   268→      const summary = this.getImplementationSummary(specUlid);
   269→      if (summary) {
   270→        summaries.push(summary);
   271→      }
   272→    }
   273→    return summaries;
   274→  }
   275→
   276→  /**
   277→   * Get stats about alignment
   278→   */
   279→  getStats(): {
   280→    totalSpecs: number;
   281→    specsWithTasks: number;
   282→    alignedSpecs: number;
   283→    orphanedSpecs: number;
   284→  } {
   285→    let specsWithTasks = 0;
   286→    let alignedSpecs = 0;
   287→    let orphanedSpecs = 0;
   288→
   289→    for (const specUlid of this.specItems.keys()) {
   290→      const taskUlids = this.specToTasks.get(specUlid) || [];
   291→      if (taskUlids.length > 0) {
   292→        specsWithTasks++;
   293→        const summary = this.getImplementationSummary(specUlid);
   294→        if (summary?.isAligned) {
   295→          alignedSpecs++;
   296→        }
   297→      } else {
   298→        orphanedSpecs++;
   299→      }
   300→    }
   301→
   302→    return {
   303→      totalSpecs: this.specItems.size,
   304→      specsWithTasks,
   305→      alignedSpecs,
   306→      orphanedSpecs,
   307→    };
   308→  }
   309→}
   310→
   311→// ============================================================
   312→// SYNC FUNCTIONS
   313→// ============================================================
   314→
   315→/**
   316→ * Result of syncing spec implementation status
   317→ */
   318→export interface SyncResult {
   319→  synced: boolean;
   320→  specUlid: string;
   321→  specTitle: string;
   322→  previousStatus: ImplementationStatus;
   323→  newStatus: ImplementationStatus;
   324→}
   325→
   326→/**
   327→ * Sync a spec item's implementation status based on its linked tasks.
   328→ * Called after task state changes (start, complete, etc.).
   329→ *
   330→ * @returns SyncResult if status changed, null if no change needed or no spec_ref
   331→ */
   332→export async function syncSpecImplementationStatus(
   333→  ctx: KspecContext,
   334→  task: LoadedTask,
   335→  allTasks: LoadedTask[],
   336→  allItems: LoadedSpecItem[],
   337→  refIndex: ReferenceIndex,
   338→): Promise<SyncResult | null> {
   339→  // Skip if task has no spec_ref
   340→  if (!task.spec_ref) {
   341→    return null;
   342→  }
   343→
   344→  // Resolve the spec reference
   345→  const result = refIndex.resolve(task.spec_ref);
   346→  if (!result.ok) {
   347→    return null;
   348→  }
   349→
   350→  // Find the spec item
   351→  const specItem = allItems.find((item) => item._ulid === result.ulid);
   352→  if (!specItem) {
   353→    return null;
   354→  }
   355→
   356→  // Build alignment index to calculate expected status
   357→  const alignmentIndex = new AlignmentIndex(allTasks, allItems);
   358→  alignmentIndex.buildLinks(refIndex);
   359→
   360→  const expectedStatus = alignmentIndex.calculateExpectedStatus(specItem._ulid);
   361→  const currentStatus = specItem.status?.implementation || "not_started";
   362→
   363→  // No change needed
   364→  if (currentStatus === expectedStatus) {
   365→    return null;
   366→  }
   367→
   368→  // Update the spec item
   369→  await updateSpecItem(ctx, specItem, {
   370→    status: {
   371→      maturity: specItem.status?.maturity || "draft",
   372→      implementation: expectedStatus,
   373→    },
   374→  });
   375→
   376→  return {
   377→    synced: true,
   378→    specUlid: specItem._ulid,
   379→    specTitle: specItem.title,
   380→    previousStatus: currentStatus,
   381→    newStatus: expectedStatus,
   382→  };
   383→}
